-- =========================
-- TABELA: cfop
-- =========================
-- Tabela de CFOP (Codigo Fiscal de Operacoes e Prestacoes) - grupos 5.000 (saidas para
-- o mesmo estado) e 6.000 (saidas para outros estados), fonte: SEFAZ-PE. Somente leitura
-- pelo usuario, servindo apenas para selecao/listagem na emissao da nota fiscal.
CREATE TABLE cfop (
    codigo VARCHAR(4) PRIMARY KEY,
    descricao VARCHAR(500) NOT NULL
);

